mapper.select:
SELECT DATE_FORMAT(create_time, #{format}) AS period, COUNT(*) AS count
FROM article_view_record
WHERE create_time >= #{begin}
  AND create_time < #{end}
GROUP BY period
ORDER BY period

SELECT a.id, a.title, COUNT(c.id) AS commentCount, MAX(c.create_time) AS lastTime
FROM `comment` c
INNER JOIN article a ON c.source_id = a.id AND c.type = 0
WHERE c.delete_flag = 0
  AND a.delete_flag = 0
  AND c.create_time >= #{begin}
  AND c.create_time < #{end}
GROUP BY a.id, a.title
ORDER BY commentCount DESC, a.id ASC
LIMIT #{limit}

SELECT
    (SELECT COUNT(*) FROM sys_user WHERE delete_flag = 0) AS userTotal,
    (SELECT COUNT(*) FROM sys_user WHERE delete_flag = 0 AND create_time >= #{begin} AND create_time < #{end}) AS newUser,
    (SELECT COUNT(*) FROM sys_user WHERE delete_flag = 0 AND create_time >= CURDATE()) AS todayNewUser,
    (SELECT COUNT(*) FROM (
        SELECT user_id FROM article WHERE delete_flag = 0 AND user_id IS NOT NULL AND create_time >= #{begin} AND create_time < #{end}
        UNION
        SELECT user_id FROM `comment` WHERE delete_flag = 0 AND create_time >= #{begin} AND create_time < #{end}
    ) t) AS activeUserCount,
    (SELECT COUNT(*) FROM sys_user WHERE delete_flag = 0 AND status = 0) AS disabledCount

SELECT a.id, a.title, COUNT(v.id) AS viewCount
FROM article_view_record v
INNER JOIN article a ON v.article_id = a.id
WHERE v.create_time >= #{begin}
  AND v.create_time < #{end}
  AND a.delete_flag = 0
GROUP BY a.id, a.title
ORDER BY viewCount DESC, a.id ASC
LIMIT #{limit}
